// app_state.h
// Everything the cinema remembers between web requests: the row, the waitlist, the booking lists,
// the hall and the customer names. Teacher-provided server code: students do not edit this file.

#ifndef APP_STATE_H                     // guard: stops this file being included twice
#define APP_STATE_H                     // mark the file as included

#include "config.h"                     // all array sizes

struct AppState                         // one object holding the whole cinema
{
    int row[ROW_SIZE];                  // Stage 2 and 4: one row of seats
    int waitlist[MAX_WAIT];             // Stage 3: ticket IDs waiting
    int waitCount;                      // how many are waiting
    int bookings[MAX_BOOKINGS];         // Stage 4 to 6: ticket IDs in booking order (unsorted)
    int bookingCount;                   // how many bookings
    int sorted[MAX_BOOKINGS];           // Stage 5 and 6: the last sorted copy of bookings
    int sortedCount;                    // how many values in sorted (0 = not sorted yet)
    int online[MAX_BOOKINGS];           // Stage 7: online bookings, sorted
    int onlineCount;                    // how many online bookings
    int counter[MAX_BOOKINGS];          // Stage 7: counter bookings, sorted
    int counterCount;                   // how many counter bookings
    int hall[ROWS][COLS];               // Stage 8: the full hall
    char names[MAX_CUSTOMERS][NAME_LEN];    // Stage 9: customer names
    int nameCount;                      // how many names
};

void resetState(AppState& state);       // puts back the same opening-night data used in the teaching guide

#endif                                  // end of the include guard
